import { requireAuth, apiSuccess, apiError, handleApiError } from "@/lib/utils/api";
import { revokeSession } from "@/lib/services/profile-service";

// Session IDs are generated by Better Auth (nanoid/cuid: alphanum
// 16-64 chars, NOT a UUID). We only validate a reasonable format to
// reject junk; the real security comes from the `userId` filter in
// `revokeSession` (impossible to revoke another user's session).
const SESSION_ID_RE = /^[A-Za-z0-9_-]{16,64}$/;

export async function DELETE(_request: Request, { params }: { params: Promise<{ id: string }> }) {
  try {
    const session = await requireAuth();
    const { id } = await params;
    if (!SESSION_ID_RE.test(id)) return apiError("profile.errors.invalidSessionId");
    const result = await revokeSession(session.user.id, id);
    return apiSuccess(result);
  } catch (error) {
    return handleApiError(error);
  }
}
